//print_r($data); exit;
// Проходим по массиву данных.
foreach ($data as $item) {
    // Проверяем, существует ли сущность.
    $entity_type = $item['entity_type'];
    $entity_id = $item['entity_id'];
    $metatags = $item['metatags'];

    $entity = \Drupal::entityTypeManager()->getStorage($entity_type)->load($entity_id);
    if (!$entity) {
        \Drupal::logger('custom_metatag_import')->warning("Сущность с ID {$entity_id} не найдена.");
        continue;
    }

    // Проверяем, поддерживает ли сущность метатеги.
    if (!$entity->hasField('metatag')) {
        \Drupal::logger('custom_metatag_import')->warning("Сущность с ID {$entity_id} не имеет поля metatag.");
        continue;
    }

    // Формируем данные метатегов.
    $metatag_values = [];
    foreach ($metatags as $key => $value) {
        $metatag_values[$key] = is_array($value) ? $value['value'] : $value;
    }
    if(!$metatag_values['title'] && !$metatag_values['description']) {
        continue;
    }

//print_r($metatag_values); exit;
//        $metatag_values = [
//        'title' => ['value' => 'Новый заголовок'],
//        'description' => ['value' => 'Новое описание'],
//        'canonical' => ['value' => 'https://example.com'],
//    ];
    print_r($entity_id) .PHP_EOL;
    print_r($metatag_values);
    // Устанавливаем метатеги.
    $entity->set('field_metatag', json_encode($metatag_values));

    // Сохраняем сущность.
    try {
        $entity->save();
        echo 'saved';
    } catch (\Exception $e) {
        \Drupal::logger('custom_metatag_import')->error('Ошибка при сохранении метатегов: @message', ['@message' => $e->getMessage()]);
    }

    \Drupal::logger('custom_metatag_import')->info("Метатеги для сущности с ID {$entity_id} успешно импортированы.");
//    exit;
}

\Drupal::logger('custom_metatag_import')->info('Импорт метатегов завершён.');
